"""Regenerates synthetic_bars.json (deterministic). Run from anywhere:

    python tests/fixtures/make_synthetic.py

Bars use the measured /v2/equities/bars/daily field names (docs/api-field-mapping.md);
TOPIX uses /v2/indices/bars/daily/topix names. Values are synthetic test data.
"""
from __future__ import annotations

import json
import math
import random
from datetime import date, timedelta
from pathlib import Path

OUT = Path(__file__).resolve().parent / "synthetic_bars.json"
START = date(2023, 1, 4)
N_DAYS = 420


def business_days(start: date, n: int) -> list[str]:
    out, d = [], start
    while len(out) < n:
        if d.weekday() < 5:
            out.append(d.isoformat())
        d += timedelta(days=1)
    return out


def r2(x: float) -> float:
    return round(x, 2)


def bar(code, day, o, h, l, c, vol, factor=1.0, adj_ratio=1.0, ul="0", ll="0"):
    """adj_ratio: adjusted = raw * adj_ratio (cumulative factor after this day)."""
    return {
        "Date": day, "Code": code,
        "O": r2(o), "H": r2(h), "L": r2(l), "C": r2(c), "UL": ul, "LL": ll,
        "Vo": float(vol), "Va": float(round(vol * c)), "AdjFactor": factor,
        "AdjO": r2(o * adj_ratio), "AdjH": r2(h * adj_ratio), "AdjL": r2(l * adj_ratio), "AdjC": r2(c * adj_ratio),
        "AdjVo": float(round(vol / adj_ratio)), "MktCap": None,
    }


def ohlc(rng, prev, close):
    o = prev * (1 + rng.uniform(-0.004, 0.004))
    h = max(o, close) * (1 + rng.uniform(0, 0.01))
    l = min(o, close) * (1 - rng.uniform(0, 0.01))
    return o, h, l


def main() -> None:
    days = business_days(START, N_DAYS)
    rng = random.Random(20261121)

    # TOPIX random walk
    topix, t_rets = [], []
    level = 2500.0
    for i, d in enumerate(days):
        r = 0.0 if i == 0 else rng.gauss(0.0003, 0.009)
        t_rets.append(r)
        prev = level
        level = level * (1 + r)
        o, h, l = ohlc(rng, prev, level)
        topix.append({"Date": d, "O": r2(o), "H": r2(h), "L": r2(l), "C": r2(level)})

    stocks = {}
    specs = {"90010": (1.2, 0.012, 1800.0), "90020": (0.7, 0.015, 650.0), "90030": (1.0, 0.02, 4200.0)}
    for code, (beta, idio, start) in specs.items():
        rows, price = [], start
        for i, d in enumerate(days):
            # use the *rounded* TOPIX returns so the stock tracks the stored index
            rt = 0.0 if i == 0 else topix[i]["C"] / topix[i - 1]["C"] - 1
            r = 0.0 if i == 0 else beta * rt + rng.gauss(0, idio) + 0.004 * math.sin(i / 23.0)
            prev = price
            price = price * (1 + r)
            o, h, l = ohlc(rng, prev, price)
            vol = rng.randint(50_000, 400_000)
            ul = ll = "0"
            if code == "90030" and i in (150, 151, 300):
                vol = 0  # zero-volume days (excluded from beta)
            if code == "90020" and i == 210:
                ul = "1"
            if code == "90020" and i == 330:
                ll = "1"
            rows.append(bar(code, d, o, h, l, price, vol, ul=ul, ll=ll))
        stocks[code] = rows

    # Split stock: 1:2 split effective on day 300 (AdjFactor 0.5 on that day).
    split_idx = 300
    split_rows, price = [], 3000.0
    for i, d in enumerate(days):
        r = 0.0 if i == 0 else rng.gauss(0.0002, 0.011)
        prev = price
        price = price * (1 + r)            # economic (post-split basis) price path
        o, h, l = ohlc(rng, prev, price)
        vol = rng.randint(80_000, 200_000)
        if i < split_idx:   # raw prices were twice the post-split basis
            split_rows.append(bar("90040", d, o * 2, h * 2, l * 2, price * 2, vol, 1.0, 0.5))
        else:
            split_rows.append(bar("90040", d, o, h, l, price, vol * 2, 0.5 if i == split_idx else 1.0, 1.0))

    # Cross stock: smooth sine so 25/75 crosses happen at known places.
    cross_rows = []
    for i, d in enumerate(days):
        c = 1000 + 150 * math.sin(2 * math.pi * i / 140.0) + 0.2 * i
        prev = 1000 + 150 * math.sin(2 * math.pi * (i - 1) / 140.0) + 0.2 * (i - 1)
        cross_rows.append(bar("90050", d, prev, max(prev, c) + 1, min(prev, c) - 1, c, 100_000))

    short_rows = []
    for i, d in enumerate(days[-10:]):
        c = 500 + i * 3 - (i % 3) * 4
        short_rows.append(bar("90060", d, c - 1, c + 2, c - 3, c, 10_000))

    OUT.write_text(json.dumps({
        "_comment": "Synthetic data generated by make_synthetic.py (deterministic). Not real market data.",
        "topix": topix,
        "stocks": stocks,
        "split_stock": {"code": "90040", "split_date": days[split_idx], "adj_factor": 0.5, "bars": split_rows},
        "cross_stock": cross_rows,
        "short_stock": short_rows,
    }, ensure_ascii=False, indent=None, separators=(",", ":")) + "\n", encoding="utf-8")
    print(f"wrote {OUT} ({len(days)} business days, {days[0]}..{days[-1]})")


if __name__ == "__main__":
    main()
